-- V2__identity_and_access.sql
-- organizations/users stay uuid (unpredictable growth, generated by the app, not hand-
-- curated); roles/permissions were created in V1 alongside the other lookup tables.
--
-- RBAC: 5 roles · 44 permissions · additive model.
-- Effective access = union of all assigned roles, narrowed by scope in application policy.
-- NestJS checks permission codes, not role names.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE organizations (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name       varchar(255) NOT NULL,
    slug       varchar(255) NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id   uuid NOT NULL REFERENCES organizations(id),
    email             varchar(320) NOT NULL UNIQUE,
    oauth_provider_id smallint NOT NULL REFERENCES oauth_providers(oauth_provider_id),
    oauth_id          varchar(255) NOT NULL,
    full_name         varchar(255),
    created_at        timestamptz NOT NULL DEFAULT now(),
    UNIQUE (oauth_provider_id, oauth_id)
);
CREATE INDEX idx_users_organization_id ON users(organization_id);

CREATE TABLE user_roles (
    user_id    uuid NOT NULL REFERENCES users(id),
    role_id    smallint NOT NULL REFERENCES roles(role_id),
    granted_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_id)
);
CREATE INDEX idx_user_roles_role_id ON user_roles(role_id);

CREATE TABLE role_permissions (
    role_id       smallint NOT NULL REFERENCES roles(role_id),
    permission_id smallint NOT NULL REFERENCES permissions(permission_id),
    PRIMARY KEY (role_id, permission_id)
);
CREATE INDEX idx_role_permissions_permission_id ON role_permissions(permission_id);

