-- ── Role → Permission mappings ────────────────────────────────────────────────
-- SELECT-based inserts keep this readable and free of hardcoded numeric ids.

-- platform_admin
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.role_id, p.permission_id FROM roles r, permissions p
WHERE r.role_name = 'platform_admin' AND p.permission_code IN (
    'user.create.self', 'user.read.self', 'user.update.self',
    'user.read.org', 'user.read.all',
    'role.read', 'role.assign', 'role.remove', 'role.catalogue.write',
    'org.create', 'org.read.all', 'org.suspend', 'org.read.self',
    'course.community.read'
);

